#include "item_drag.hpp"
#include "item_placement.hpp"
#include "item_icons.hpp"
#include <cmath>
@interface MuDragGhost:NSView
@property(nonatomic,strong) NSImage* image;
@property(nonatomic) BOOL valid;
@end
@implementation MuDragGhost
- (NSView*)hitTest:(NSPoint)point{return nil;}
- (void)drawRect:(NSRect)rect{}
@end
namespace {struct Container{unsigned flag;__weak NSView* view;mu::client::ItemSlots items;std::shared_ptr<const mu::ui::ItemCatalog> catalog;std::string root,language;};}
@implementation MuItemDrag{mu::client::EquipmentAttributes characterAttributes;std::vector<Container> containers;int sourceIndex,sourceSlot;NSPoint start;BOOL dragging,armed,picked;MuDragGhost* ghost;MuHoveredItemView* heldView;NSView* hint;id monitor;}
- (instancetype)init{self=[super init];if(self){__weak MuItemDrag* weak=self;monitor=[NSEvent addLocalMonitorForEventsMatchingMask:(NSEventMaskMouseMoved|NSEventMaskLeftMouseDown|NSEventMaskLeftMouseUp|NSEventMaskRightMouseDown|NSEventMaskKeyDown) handler:^NSEvent*(NSEvent* event){MuItemDrag* owner=weak;if(!owner||!owner.carrying||![owner handlesWindow:event.window])return event;if(owner.pending)return nil;if(event.type==NSEventTypeKeyDown&&event.keyCode==53){[owner cancel];return nil;}if(event.type==NSEventTypeRightMouseDown){[owner cancel];return nil;}if(event.type==NSEventTypeMouseMoved){[owner drag:event];return nil;}if(event.type==NSEventTypeLeftMouseDown)return nil;if(event.type==NSEventTypeLeftMouseUp){[owner finish:event];return nil;}return event;}];}return self;}
- (void)dealloc{if(monitor)[NSEvent removeMonitor:monitor];}
- (BOOL)handlesWindow:(NSWindow*)window{return armed&&sourceIndex<int(containers.size())&&containers[sourceIndex].view.window==window;}
- (BOOL)carrying{return picked;}
- (void)setAttributes:(const mu::client::EquipmentAttributes&)attributes{characterAttributes=attributes;}
- (mu::client::EquipmentAttributes)attributes{return characterAttributes;}
- (BOOL)hidesItemInContainer:(unsigned)flag slot:(unsigned)slot{return picked&&armed&&sourceIndex<int(containers.size())&&containers[sourceIndex].flag==flag&&unsigned(sourceSlot)==slot;}
- (void)redrawContainers{for(auto& container:containers){if([container.view respondsToSelector:@selector(refreshPicked)])[container.view performSelector:@selector(refreshPicked)];container.view.needsDisplay=YES;}}
- (void)registerContainer:(unsigned)flag view:(NSView*)view items:(const mu::client::ItemSlots&)items root:(const std::string&)root language:(const std::string&)language{if(armed&&!self.pending)[self cancel];Container next{flag,view,items,mu::ui::load_item_catalog(std::filesystem::path(root)/"Data",language),root,language};for(auto& container:containers)if(container.flag==flag){container=std::move(next);return;}containers.push_back(std::move(next));}
- (int)cell:(NSEvent*)event container:(const Container&)container{NSView* view=container.view;if(!view.superview||event.window!=view.window)return -1;auto p=[view convertPoint:event.locationInWindow fromView:nil];p.x*=190/view.bounds.size.width;p.y*=429/view.bounds.size.height;if(container.flag==0){int slot=mu::ui::equipment_cell(p.x,p.y);if(slot>=0)return slot;}CGFloat top=container.flag==0?200:36;int rows=container.flag==0?8:15;if(p.x<15||p.x>=175||p.y<top||p.y>=top+rows*20)return -1;return (container.flag==0?12:0)+int((p.y-top)/20)*8+int((p.x-15)/20);}
- (void)begin:(NSEvent*)event inView:(NSView*)view{if(picked)return;[self cancel];if(self.pending)return;for(unsigned n=0;n<containers.size();n++){auto& c=containers[n];if(c.view!=view)continue;int cell=[self cell:event container:c];if(cell<0)return;int slot=mu::ui::item_at_cell(c.items,*c.catalog,c.flag,cell);if(slot<0)return;sourceIndex=n;sourceSlot=slot;start=event.locationInWindow;armed=YES;return;}}
- (int)target:(NSEvent*)event move:(mu::client::ItemMove&)move{if(!armed||sourceIndex>=int(containers.size()))return -1;auto& source=containers[sourceIndex];auto found=source.items.find(sourceSlot);if(found==source.items.end())return -1;for(auto& target:containers){int cell=[self cell:event container:target];if(cell<0)continue;auto point=[target.view convertPoint:event.locationInWindow fromView:nil];point.x*=190/target.view.bounds.size.width;point.y*=429/target.view.bounds.size.height;int pickedCell=mu::ui::picked_item_cell(point.x,point.y,target.flag,source.catalog->at(found->second.index));if(pickedCell<0)return -1;unsigned destination=pickedCell;if(source.flag==target.flag&&unsigned(sourceSlot)==destination)return -1;if(!mu::ui::can_place_item(target.items,*target.catalog,target.flag,destination,found->second,source.flag==target.flag?sourceSlot:-1,self.baseClass))return -1;move={source.flag,unsigned(sourceSlot),target.flag,destination};return destination;}return -1;}
- (void)drag:(NSEvent*)event{if(!armed||self.pending)return;if(!picked&&!dragging&&std::hypot(event.locationInWindow.x-start.x,event.locationInWindow.y-start.y)<4)return;dragging=YES;auto& source=containers[sourceIndex];auto& item=source.items.at(sourceSlot);auto& a=source.catalog->at(item.index);auto host=source.view.superview;if(!host)return;if(!ghost){ghost=[MuDragGhost new];ghost.image=mu::ui::cached_item_icon(source.root,source.language,item);[host addSubview:ghost];}auto p=[host convertPoint:event.locationInWindow fromView:nil];CGFloat scale=source.view.bounds.size.width/190;ghost.frame=NSMakeRect(p.x-a.width*10*scale,p.y-a.height*10*scale,a.width*20*scale,a.height*20*scale);mu::client::ItemMove move;ghost.valid=[self target:event move:move]>=0;if(!heldView)heldView=[MuHoveredItemView new];[heldView showItem:item root:source.root language:source.language rect:ghost.bounds inView:ghost];[hint removeFromSuperview];hint=nil;for(auto& target:containers){int cell=[self cell:event container:target];if(cell<0)continue;auto point=[target.view convertPoint:event.locationInWindow fromView:nil];CGFloat factor=target.view.bounds.size.width/190;int anchor=mu::ui::picked_item_cell(point.x/factor,point.y/factor,target.flag,a);if(anchor<0)continue;NSRect rect;if(target.flag==0&&anchor<12){auto r=mu::ui::equipment_rect(anchor);rect=NSMakeRect(r.x*factor,r.y*factor,r.width*factor,r.height*factor);}else{unsigned base=target.flag==0?12:0;rect=NSMakeRect((15+(anchor-base)%8*20)*factor,((target.flag==0?200:36)+(anchor-base)/8*20)*factor,a.width*20*factor,a.height*20*factor);}hint=[[MuDragGhost alloc] initWithFrame:rect];hint.wantsLayer=YES;hint.layer.backgroundColor=(ghost.valid?[NSColor colorWithRed:.1 green:.4 blue:.8 alpha:.4]:[NSColor colorWithRed:1 green:.2 blue:.2 alpha:.4]).CGColor;[target.view addSubview:hint];break;}ghost.needsDisplay=YES;}
- (BOOL)finish:(NSEvent*)event{if(!armed||self.pending)return NO;if(!picked){picked=YES;dragging=YES;[self drag:event];[self redrawContainers];return YES;}auto& source=containers[sourceIndex];if(source.flag==0&&self.sellView.superview&&event.window==self.sellView.window&&NSPointInRect([self.sellView convertPoint:event.locationInWindow fromView:nil],self.sellView.bounds)&&self.onSell){self.onSell(sourceSlot);return YES;}int cell=[self cell:event container:source];auto point=[source.view convertPoint:event.locationInWindow fromView:nil];CGFloat factor=source.view.bounds.size.width/190;if(cell>=0&&mu::ui::picked_item_cell(point.x/factor,point.y/factor,source.flag,source.catalog->at(source.items.at(sourceSlot).index))==sourceSlot){[self cancel];return YES;}mu::client::ItemMove move;BOOL accepted=[self target:event move:move]>=0;if(accepted&&self.onTransfer){[heldView hide];heldView=nil;[hint removeFromSuperview];hint=nil;[ghost removeFromSuperview];ghost=nil;self.onTransfer(move);}else {BOOL overContainer=NO;for(auto& c:containers)if(c.view.superview&&c.view.window==event.window&&NSPointInRect([c.view convertPoint:event.locationInWindow fromView:nil],c.view.bounds))overContainer=YES;auto front=[event.window.contentView hitTest:[event.window.contentView convertPoint:event.locationInWindow fromView:nil]];BOOL overWorld=front==self.dropView||[front isDescendantOf:self.dropView];if(overWorld&&!overContainer&&source.flag==0&&sourceSlot>=12&&self.dropView.window==event.window&&NSPointInRect([self.dropView convertPoint:event.locationInWindow fromView:nil],self.dropView.bounds)&&self.onDrop)self.onDrop(sourceSlot);else [self drag:event];}return YES;}
- (void)cancel{armed=dragging=picked=NO;[heldView hide];heldView=nil;[hint removeFromSuperview];hint=nil;[ghost removeFromSuperview];ghost=nil;[self redrawContainers];}
@end
